package pzvrphysicality;
import java.util.*;import local.pzvr.*;import viewpoint.core.Frame;import viewpointvr.physics.CollisionShape;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;import zombie.core.skinnedmodel.model.ModelMesh;
/** The current successful native phone drawer is the only source of this external contact offer. */
public final class NativeHeldContact {
 private record Receipt(NativeHeldAccess access,NativeHeldFallback.Capture capture,NativeHeldFallback.Slot slot,NativeHeldFallback.Drawer drawer,ModelMesh mesh,NativeHeldFbxCpu.Data geometry,Frame frame,long epoch,Thread owner){}
 private static final class State{final HeldContactExternal.Offer offer;float[] matrix;boolean corrected;State(HeldContactExternal.Offer value,float[] m){offer=value;matrix=m.clone();}}
 private static final IdentityHashMap<Frame,List<State>> offers=new IdentityHashMap<>();private static volatile String detail="Phone FBX contacts Off";
 private static final HeldContactExternal.Source source=new HeldContactExternal.Source(){
  public List<HeldContactExternal.Offer> targets(Frame frame,IsoPlayer actor,long now){List<State> list;synchronized(offers){list=offers.get(frame);list=list==null?List.of():List.copyOf(list);}return list.stream().map(s->s.offer).filter(o->o.actor()==actor&&current(o,now)).toList();}
  public boolean current(HeldContactExternal.Offer offer,long now){if(offer==null||offer.source()!=this||!(offer.receipt() instanceof Receipt r)||!provenance(offer,r,now))return false;State state=state(offer,r);return state!=null&&Arrays.equals(state.matrix,Arrays.copyOfRange(r.drawer.values(),r.drawer.first()*68,r.drawer.first()*68+16));}
  public boolean corrected(HeldContactExternal.Offer offer,float[] pose){if(offer==null||!(offer.receipt() instanceof Receipt r))return false;synchronized(NativeHeldFallback.class){var state=state(offer,r);if(state==null||state.corrected||!current(offer,System.nanoTime()))return false;boolean accepted=r.access.corrected(r.capture,r.slot,r.drawer,offer.pose(),pose,offer.units(),()->provenance(offer,r,System.nanoTime()));if(!accepted)return false;state.matrix=Arrays.copyOfRange(r.drawer.values(),r.drawer.first()*68,r.drawer.first()*68+16);state.corrected=true;detail="Same-frame phone/wrist/socket contact correction committed";return true;}}
  public void clear(){synchronized(offers){offers.clear();}detail="Phone FBX contacts waiting";}
 };
 private static State state(HeldContactExternal.Offer offer,Receipt r){synchronized(offers){var list=offers.get(r.frame);if(list!=null)for(var state:list)if(state.offer==offer)return state;return null;}}
 private static boolean provenance(HeldContactExternal.Offer offer,Receipt r,long now){var rig=WorldRigCapture.forScene(r.frame.scene,now);return Thread.currentThread()==r.owner&&now>=offer.time()&&now-offer.time()<=150_000_000L&&NativeHeldFallback.current(r.epoch,r.capture)&&r.access.drawerCurrent(r.capture,r.slot,r.drawer)&&NativeHeldFbxCpu.get(r.mesh)==r.geometry&&HeldContactDriver.admits(r.frame,offer.actor(),now)&&Engine.latestInput==offer.input()&&offer.input().focused()&&rig!=null&&rig.generation()==offer.rigGeneration()&&rig.actor()==offer.actor()&&rig.inputTime()==offer.input().time();}
 static void configure(boolean enabled){source.clear();if(!HeldContactExternal.register(source,enabled)&&enabled)detail="Phone contact registry capacity unavailable";else detail=enabled?"Phone contacts waiting for original FBX CPU receipt":"Phone FBX contacts Off";}
 static void publish(NativeHeldAccess access,NativeHeldFallback.Capture capture,NativeHeldFallback.Slot slot,NativeHeldFallback.Drawer drawer,long epoch,ModelMesh mesh){
  if(!HeldContactDriver.enabled()||!(capture.frame() instanceof Frame frame)||!(capture.actor() instanceof IsoPlayer actor)||!(slot.item() instanceof InventoryItem item))return;long now=System.nanoTime();var data=NativeHeldFbxCpu.get(mesh);var rig=WorldRigCapture.forScene(frame.scene,now);if(data==null){detail="Phone contact unavailable: exact native FBX CPU payload cold";return;}if(!HeldContactDriver.admits(frame,actor,now)||rig==null||rig.actor()!=actor||!rig.fresh(now)||rig.scene()!=frame.scene||rig.inputTime()!=Engine.latestInput.time()||rig.hand(slot.side())==null||Math.abs(frame.camX-rig.camera().x())>.0001||Math.abs(frame.camY-rig.camera().y())>.0001||Math.abs(frame.camZ*Math.sqrt(6)-rig.camera().height())>.0001)return;
  try{var hand=rig.hand(slot.side());float[] pose=HeldContactGeometry.pose(hand),matrix=Arrays.copyOfRange(drawer.values(),drawer.first()*68,drawer.first()*68+16);var shape=ItemMesh.fromRendered(data.vertices(),data.faces(),matrix,frame.camX,frame.camY,frame.camZ,pose);float[] vertices=shape.vertices();double radius=0;for(int n=0;n<vertices.length;n+=3)radius=Math.max(radius,Math.sqrt(vertices[n]*vertices[n]+vertices[n+1]*vertices[n+1]+vertices[n+2]*vertices[n+2]));if(radius<.005*hand.units()||radius>.75*hand.units())throw new IllegalArgumentException("Phone contact mesh reach budget");float mass=item.getActualWeight();if(!Float.isFinite(mass)||mass<=0||mass>20)return;var receipt=new Receipt(access,capture,slot,drawer,mesh,data,frame,epoch,Thread.currentThread());var offer=new HeldContactExternal.Offer(source,receipt,actor,item,slot.side(),frame.scene,Engine.latestInput,rig.generation(),epoch,now,hand.units(),Math.max(.01f,mass),new CollisionShape(vertices,shape.faces(),new float[0],false),data,pose);
   synchronized(offers){if(offers.size()>=6&&!offers.containsKey(frame))offers.clear();var list=offers.computeIfAbsent(frame,key->new ArrayList<>());list.removeIf(state->state.offer.side()==slot.side());list.add(new State(offer,matrix));}HeldContactExternal.changed(source);detail="Exact same-frame phone FBX contact offered";
  }catch(RuntimeException|LinkageError unavailable){detail="Phone contact payload rejected: "+unavailable.getClass().getSimpleName();}
 }
 static void consume(Object raw){if(raw instanceof Frame frame){boolean any;synchronized(offers){any=offers.containsKey(frame);}try{if(any)HeldContactDriver.capture(frame);}catch(RuntimeException|LinkageError unavailable){unavailable();}}}
 static void unavailable(){detail="Phone contacts unavailable; original successful visual retained";}
 static void rejected(String reason){detail="Phone native contact pose retained: "+reason;}
 static void finish(Object raw){if(raw instanceof Frame frame){synchronized(offers){offers.remove(frame);}try{HeldContactDriver.finishExternal(source,frame.scene);}catch(RuntimeException|LinkageError unavailable){unavailable();}}}
 public static String status(){return detail;}
 private NativeHeldContact(){}
}
